let connectVisited = false;
let artKind = "usa";
let visited = new Set();
let saved = new Set();

const byName = (name) => parks.find((p) => p.name === name) || parks.find((p) => p.slug === name);
const byId = (id) => parks.find((p) => p.slug === id || p.name === id);
const clean = (t) => (t || "").replace(/\s*\(\s*$/, "").trim();
const esc = (t) => String(t || "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const slug = (p) => p.slug || p.name;
const kindOf = (p) => p.kind || "national_park";
const kindCount = (kind) => parks.filter((p) => kindOf(p) === kind).length;
const kindLabel = (kind) => KIND_LABEL[kind] || "place";

function loadSet(key) {
  try {
    return new Set(JSON.parse(localStorage.getItem(key) || "[]"));
  } catch (e) {
    return new Set();
  }
}
function storeSet(key, set) {
  try {
    localStorage.setItem(key, JSON.stringify([...set]));
  } catch (e) {}
}

function radius(p) {
  const [x1, y1, x2, y2] = p.shape.bbox;
  return Math.max(Math.abs(x1), Math.abs(y1), Math.abs(x2), Math.abs(y2), 12);
}
function fitBox(p, pad = 1.22) {
  const [x1, y1, x2, y2] = p.shape.bbox;
  const cx = (x1 + x2) / 2;
  const cy = (y1 + y2) / 2;
  const s = Math.max(x2 - x1, y2 - y1, 24) * pad;
  return `${cx - s / 2} ${cy - s / 2} ${s} ${s}`;
}
function fillFor(p) {
  if (kindOf(p) === "national_park") return p.acres > 1000000 ? "#e8c572" : "#d4784a";
  return FILL[kindOf(p)] || "#d4784a";
}
function miniMap(p) {
  const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  svg.setAttribute("viewBox", fitBox(p));
  svg.setAttribute("aria-hidden", "true");
  const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
  path.setAttribute("d", p.shape.d);
  path.setAttribute("fill", fillFor(p));
  svg.append(path);
  return svg;
}
function setPhoto(el, p) {
  el.textContent = "";
  el.append(miniMap(p));
}

function ordered() {
  const a = byId(bigName);
  const b = byId(smallName);
  if (!a || !b) return [a, b];
  if (a.slug === b.slug) {
    const other = parks.find((p) => p.slug !== a.slug) || a;
    return a.acres >= other.acres ? [a, other] : [other, a];
  }
  return a.acres >= b.acres ? [a, b] : [b, a];
}

function neighbors(p) {
  const sorted = parks.slice().sort((a, b) => a.acres - b.acres);
  const i = sorted.findIndex((x) => x.slug === p.slug);
  return { smaller: sorted[i - 1], larger: sorted[i + 1] };
}

function yellowstoneFits(p) {
  const y = byName("Yellowstone");
  if (!y || p.slug === y.slug) return null;
  return y.acres / p.acres;
}

function interesting(p, other) {
  const bits = [];
  if (p.visitors) bits.push(`${fmt(p.visitors / Math.max(p.acres, 1), 1)} visitors per acre last year`);
  if (other && other.slug !== p.slug && p.visitors > other.visitors && p.acres < other.acres) {
    bits.push(`More visitors than ${other.name}, on less land`);
  }
  if (p.year === 1872) bits.push("The first U.S. national park");
  if ((p.states || []).includes("AK")) bits.push("Alaska holds a huge share of the country’s public land");
  return bits.join(" · ");
}

function fillDl(dl, rows) {
  dl.textContent = "";
  rows.filter((row) => row[1] && row[1] !== "0").forEach(([k, v]) => {
    const dt = document.createElement("dt");
    dt.textContent = k;
    const dd = document.createElement("dd");
    dd.textContent = v;
    dl.append(dt, dd);
  });
}

function statsRows(p) {
  const rows = [
    ["Acres", fmt(p.acres)],
    ["Square km", fmt(p.km2, 1)],
    ["Where", (p.states || []).join(" / ") || "—"],
  ];
  if (p.visitors) rows.splice(2, 0, ["Visitors", fmt(p.visitors)]);
  if (p.year) {
    rows.push(["Established", String(p.year)]);
    rows.push(["Age", `${new Date().getFullYear() - p.year} years`]);
  }
  return rows;
}

function showFacts(p, other) {
  if (!p) return;
  focus = p.slug;
  const n = kindCount(kindOf(p));
  $("#factKicker").textContent = `#${p.rank} of ${fmt(n)} ${kindLabel(kindOf(p))}s by land`;
  $("#factName").textContent = p.name;
  fillDl($("#factStats"), statsRows(p));
  $("#factCopy").textContent = clean(p.description);
  $("#factExtra").textContent = interesting(p, other);
}

function updateProgress() {
  $("#progress").textContent = `${visited.size} of ${fmt(parks.length)} places visited · ${saved.size} saved`;
}

function renderCompareMode() {
  const [outer, inner] = ordered();
  if (!outer || !inner) return;
  bigName = outer.slug;
  smallName = inner.slug;
  $("#bigName").textContent = outer.name;
  $("#smallName").textContent = inner.name;
  setPhoto($("#bigPhoto"), outer);
  setPhoto($("#smallPhoto"), inner);
  const svg = $("#map");
  while (svg.firstChild) svg.removeChild(svg.firstChild);
  const r = Math.max(radius(outer), radius(inner)) * 1.16;
  svg.setAttribute("viewBox", `${-r} ${-r} ${2 * r} ${2 * r}`);
  [
    [outer, "big"],
    [inner, "small"],
  ].forEach(([p, cls]) => {
    const path = document.createElementNS("http://www.w3.org/2000/svg", "path");
    path.setAttribute("d", p.shape.d);
    path.setAttribute("class", cls);
    path.setAttribute("fill", fillFor(p));
    path.addEventListener("click", () => {
      showFacts(p, p === outer ? inner : outer);
      openDossier(p);
    });
    svg.append(path);
  });
  const addLabel = (text, y) => {
    const t = document.createElementNS("http://www.w3.org/2000/svg", "text");
    t.setAttribute("class", "label");
    t.setAttribute("x", "0");
    t.setAttribute("y", String(y));
    t.setAttribute("text-anchor", "middle");
    t.setAttribute("fill", "#f4efe6");
    t.setAttribute("font-size", String(Math.max(r * 0.05, 20)));
    t.textContent = text;
    svg.append(t);
  };
  addLabel(outer.name, -r * 0.86);
  addLabel(inner.name, r * 0.88);
  const times = outer.acres / inner.acres;
  $("#punch").textContent =
    times >= 1.05
      ? `${outer.name} could hold ${fmt(times, 1)} lands the size of ${inner.name}.`
      : `${outer.name} and ${inner.name} are nearly the same size.`;
  $("#hint").textContent = "Same scale. North is up. Tap a shape to open its page.";
  $("#pairNote").textContent = "Open a page to check it off or save it. Mix parks with forests.";
  const focused = byId(focus);
  showFacts(focused && (focused.slug === outer.slug || focused.slug === inner.slug) ? focused : outer, inner);
  history.replaceState(null, "", `#${encodeURIComponent(outer.slug)}/${encodeURIComponent(inner.slug)}`);
  updateProgress();
}

function xy(p) {
  if (typeof p.lon !== "number" || typeof p.lat !== "number") return null;
  return [p.lon, -p.lat];
}

function activeState() {
  if (stateFilter) return stateFilter;
  const p = byId(focus) || byId(bigName);
  return (p && p.states && p.states[0]) || "";
}

function mapPlaces() {
  let list = atlasList();
  if (focusStateOnly) {
    const st = activeState();
    if (st) list = list.filter((p) => (p.states || []).includes(st));
  }
  return list.filter((p) => xy(p));
}

function visitedInOrder(list) {
  const allow = new Set(list.map((p) => slug(p)));
  const out = [];
  visited.forEach((id) => {
    if (!allow.has(id)) return;
    const p = byId(id);
    if (p && xy(p)) out.push(p);
  });
  return out;
}

function renderLegend() {
  const root = $("#mapLegend");
  if (!root) return;
  root.textContent = "";
  const add = (color, label, extra) => {
    const span = document.createElement("span");
    const i = document.createElement("i");
    i.style.background = color;
    if (extra) i.className = extra;
    span.append(i, document.createTextNode(label));
    root.append(span);
  };
  KINDS.forEach((k) => add(FILL[k.id], k.label.replace(/s$/, "")));
  add("#d4784a", "Not yet", "open");
  add("#e8c572", "Visited", "visited");
}

function fitMapToMarkers(places) {
  const pts = (places || mapPlaces()).map(xy).filter(Boolean);
  if (!pts.length) {
    mapScale = 1;
    mapTx = 0;
    mapTy = 0;
    return;
  }
  let minx = 1e9;
  let miny = 1e9;
  let maxx = -1e9;
  let maxy = -1e9;
  pts.forEach(([x, y]) => {
    minx = Math.min(minx, x);
    miny = Math.min(miny, y);
    maxx = Math.max(maxx, x);
    maxy = Math.max(maxy, y);
  });
  const pad = 6;
  const w = Math.max(maxx - minx, 4) + pad * 2;
  const h = Math.max(maxy - miny, 4) + pad * 2;
  mapScale = Math.max(0.5, Math.min(14, Math.min(360 / w, 180 / h)));
  const cx = (minx + maxx) / 2;
  const cy = (miny + maxy) / 2;
  mapTx = -cx * mapScale;
  mapTy = -cy * mapScale;
}

function renderUsMapMode() {
  const svg = $("#map");
  while (svg.firstChild) svg.removeChild(svg.firstChild);
  svg.setAttribute("viewBox", "-180 -90 360 180");
  svg.setAttribute("aria-label", "U.S. map of parks and forests");

  const places = mapPlaces();
  const layer = document.createElementNS("http://www.w3.org/2000/svg", "g");
  layer.setAttribute("class", "map-layer");
  layer.setAttribute("transform", `translate(${mapTx} ${mapTy}) scale(${mapScale})`);

  const land = document.createElementNS("http://www.w3.org/2000/svg", "path");
  land.setAttribute("d", US_PATH);
  land.setAttribute("fill", "#1a211a");
  land.setAttribute("stroke", "rgba(244,239,230,.45)");
  land.setAttribute("stroke-width", "0.35");
  land.setAttribute("vector-effect", "non-scaling-stroke");
  layer.append(land);

  const trail = visitedInOrder(places);
  if (connectVisited && trail.length > 1) {
    const line = document.createElementNS("http://www.w3.org/2000/svg", "polyline");
    line.setAttribute("points", trail.map((p) => xy(p).join(",")).join(" "));
    line.setAttribute("fill", "none");
    line.setAttribute("stroke", "#e8c572");
    line.setAttribute("stroke-width", "0.45");
    line.setAttribute("stroke-opacity", "0.85");
    line.setAttribute("stroke-linecap", "round");
    line.setAttribute("stroke-linejoin", "round");
    layer.append(line);
  }

  places.forEach((p) => {
    const [cx, cy] = xy(p);
    const id = slug(p);
    const visitedHere = visited.has(id);
    const size = Math.min(2.6, Math.max(0.7, Math.log10(Math.max(2, p.acres)) / 5));
    const dot = document.createElementNS("http://www.w3.org/2000/svg", "circle");
    dot.setAttribute("cx", String(cx));
    dot.setAttribute("cy", String(cy));
    dot.setAttribute("r", String(size));
    dot.setAttribute("fill", fillFor(p));
    dot.setAttribute("fill-opacity", visitedHere ? "1" : "0.42");
    dot.setAttribute("stroke", visitedHere ? "#84f4a4" : "rgba(244,239,230,0.4)");
    dot.setAttribute("stroke-width", visitedHere ? "0.35" : "0.15");
    dot.setAttribute("cursor", "pointer");
    dot.addEventListener("click", (e) => {
      e.stopPropagation();
      showFacts(p);
      openDossier(p);
    });
    layer.append(dot);
  });

  svg.append(layer);
  syncMapTransform();
  renderLegend();
  const st = focusStateOnly ? activeState() : "";
  const seen = places.filter((p) => visited.has(slug(p))).length;
  $("#punch").textContent = st
    ? `${fmt(places.length)} places in ${st} · ${fmt(seen)} visited`
    : `${fmt(places.length)} places on the map · ${fmt(seen)} visited`;
  $("#hint").textContent = "Scroll to zoom. Drag to pan. Green ring = been there.";
  $("#pairNote").textContent = "Fit markers to plan a route. Print art makes a poster of visited places.";
  updateProgress();
}

function syncMapTransform() {
  const layer = $("#map").querySelector(".map-layer");
  if (layer) layer.setAttribute("transform", `translate(${mapTx} ${mapTy}) scale(${mapScale})`);
}

function setMapMode(on) {
  mapMode = on;
  $("#btnMap").classList.toggle("on", mapMode);
  const chrome = $("#mapChrome");
  if (chrome) {
    chrome.hidden = !mapMode;
    if (mapMode) chrome.removeAttribute("hidden");
    else chrome.setAttribute("hidden", "");
  }
  if (mapMode) {
    mapScale = 1;
    mapTx = 0;
    mapTy = 0;
    fitMapToMarkers();
  }
  draw();
}

function draw() {
  if (mapMode) return renderUsMapMode();
  renderCompareMode();
}

function closeArt() {
  const el = $("#artModal");
  if (!el) return;
  el.hidden = true;
  el.setAttribute("hidden", "");
}

function artFilename() {
  return artKind === "park" ? "parks-and-scale-park.svg" : "parks-and-scale-usa.svg";
}

function currentArtSvg() {
  return artKind === "park" ? buildParkArt() : buildUsaArt();
}

function paintArt() {
  const root = $("#artPreview");
  if (!root) return;
  // Generated SVG only; park names are escaped.
  root.innerHTML = currentArtSvg();
  $("#artUsa").classList.toggle("on", artKind === "usa");
  $("#artPark").classList.toggle("on", artKind === "park");
}

function openArt() {
  const el = $("#artModal");
  el.hidden = false;
  el.removeAttribute("hidden");
  if (!$("#artConnect").checked && connectVisited) $("#artConnect").checked = true;
  paintArt();
}

function downloadArt() {
  const blob = new Blob([currentArtSvg()], { type: "image/svg+xml;charset=utf-8" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = artFilename();
  a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 1500);
}

function printArt() {
  const w = window.open("", "_blank");
  if (!w) return;
  w.document.write(`<!doctype html><title>Parks and Scale</title><body style="margin:0;background:#0c0e0c">${currentArtSvg()}</body>`);
  w.document.close();
  w.focus();
  w.print();
}

function buildUsaArt() {
  const connect = $("#artConnect") ? $("#artConnect").checked : connectVisited;
  const places = mapPlaces();
  const trail = visitedInOrder(parks).filter((p) => xy(p));
  const shown = trail.length ? trail : places.filter((p) => visited.has(slug(p)));
  const pts = shown.map(xy).filter(Boolean);
  let minx = -125;
  let miny = -50;
  let maxx = -66;
  let maxy = -24;
  if (pts.length) {
    minx = Math.min(...pts.map((p) => p[0]));
    miny = Math.min(...pts.map((p) => p[1]));
    maxx = Math.max(...pts.map((p) => p[0]));
    maxy = Math.max(...pts.map((p) => p[1]));
  }
  const pad = 8;
  const W = 1600;
  const H = 1100;
  const w = Math.max(maxx - minx, 8) + pad * 2;
  const h = Math.max(maxy - miny, 6) + pad * 2;
  const vb = `${minx - pad} ${miny - pad} ${w} ${h}`;
  const dots = shown
    .map((p) => {
      const [x, y] = xy(p);
      const r = Math.min(1.8, Math.max(0.7, Math.log10(Math.max(2, p.acres)) / 6));
      return `<circle cx="${x}" cy="${y}" r="${r}" fill="${fillFor(p)}" stroke="#f4efe6" stroke-width="0.18"/>`;
    })
    .join("");
  const line =
    connect && shown.length > 1
      ? `<polyline fill="none" stroke="#e8c572" stroke-width="0.28" stroke-linecap="round" stroke-linejoin="round" opacity="0.9" points="${shown
          .map((p) => xy(p).join(","))
          .join(" ")}"/>`
      : "";
  const names = shown
    .slice()
    .sort((a, b) => b.acres - a.acres)
    .slice(0, 12)
    .map((p, i) => `<tspan x="70" dy="${i ? 22 : 0}">${esc(p.name)}</tspan>`)
    .join("");
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">
  <rect width="100%" height="100%" fill="#0c0e0c"/>
  <text x="70" y="86" fill="#e8c572" font-family="Fraunces, Georgia, serif" font-size="54" font-weight="800">Parks and Scale</text>
  <text x="70" y="124" fill="#d5ddd2" font-family="Nunito, sans-serif" font-size="22" font-weight="700">${fmt(shown.length)} visited · ${new Date().getFullYear()}</text>
  <svg x="40" y="150" width="1520" height="780" viewBox="${vb}" preserveAspectRatio="xMidYMid meet">
    <path d="${US_PATH}" fill="#161c16" stroke="#f4efe6" stroke-width="0.35" fill-opacity="0.95"/>
    ${line}${dots}
  </svg>
  <text x="70" y="980" fill="#d5ddd2" font-family="Nunito, sans-serif" font-size="16" font-weight="700">${names || "Check Been here to paint this map."}</text>
  <text x="70" y="1060" fill="#8d968a" font-family="Nunito, sans-serif" font-size="14">Not an official map. For reference and printing.</text>
</svg>`;
}

function buildParkArt() {
  const p = byId(focus) || byId(bigName) || parks[0];
  if (!p || !p.shape) return "<svg xmlns='http://www.w3.org/2000/svg'></svg>";
  const W = 1100;
  const H = 1400;
  const been = visited.has(slug(p));
  return `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">
  <rect width="100%" height="100%" fill="#0c0e0c"/>
  <text x="70" y="90" fill="#e8c572" font-family="Fraunces, Georgia, serif" font-size="28" font-weight="800">Parks and Scale</text>
  <text x="70" y="160" fill="#f4efe6" font-family="Fraunces, Georgia, serif" font-size="64" font-weight="800">${esc(p.name)}</text>
  <text x="70" y="200" fill="#d5ddd2" font-family="Nunito, sans-serif" font-size="22">${kindLabel(kindOf(p))} · ${fmt(p.acres)} acres · ${(p.states || []).join(" / ")}</text>
  <svg x="80" y="240" width="940" height="940" viewBox="${fitBox(p, 1.18)}" preserveAspectRatio="xMidYMid meet">
    <path d="${p.shape.d}" fill="${fillFor(p)}" fill-opacity="0.92" stroke="#f4efe6" stroke-width="2" vector-effect="non-scaling-stroke"/>
  </svg>
  <text x="70" y="1280" fill="#e8c572" font-family="Nunito, sans-serif" font-size="22" font-weight="800">${been ? "Been here" : "Not yet"}</text>
  <text x="70" y="1340" fill="#8d968a" font-family="Nunito, sans-serif" font-size="14">True-scale outline. North is up.</text>
</svg>`;
}


function openDossier(p) {
  dossierPark = p;
  $("#dossier").hidden = false;
  $("#dossier").removeAttribute("hidden");
  $("#dossierName").textContent = p.name;
  $("#dossierKicker").textContent = `${kindLabel(kindOf(p))} · #${p.rank} of ${fmt(kindCount(kindOf(p)))} · ${(p.states || []).join(" / ")}`;
  setPhoto($("#dossierMap"), p);
  fillDl($("#dossierStats"), statsRows(p));
  $("#dossierCopy").textContent = clean(p.description);
  const fun = $("#dossierFun");
  fun.textContent = "";
  const n = neighbors(p);
  const yFit = yellowstoneFits(p);
  const lines = [];
  if (n.larger) lines.push(`Next larger anywhere: ${n.larger.name} (${fmt(n.larger.acres)} acres)`);
  if (n.smaller) lines.push(`Next smaller anywhere: ${n.smaller.name} (${fmt(n.smaller.acres)} acres)`);
  if (yFit && yFit >= 1.05) lines.push(`${fmt(yFit, 1)} of these would fit in Yellowstone`);
  if (yFit && yFit < 1) lines.push(`Yellowstone would fit inside this ${fmt(1 / yFit, 1)} times`);
  if (p.visitors) lines.push(`${fmt(p.visitors / Math.max(p.acres, 1), 1)} visitors per acre in 2023`);
  if (p.year === 1872) lines.push("The first U.S. national park");
  lines.forEach((line) => {
    const li = document.createElement("li");
    li.textContent = line;
    fun.append(li);
  });
  $("#dossierWiki").href = p.wiki || "#";
  $("#dossierWiki").hidden = !p.wiki;
  $("#beenHere").classList.toggle("on", visited.has(slug(p)));
  $("#savePark").classList.toggle("on", saved.has(slug(p)));
}

function closeDossier() {
  $("#dossier").hidden = true;
  $("#dossier").setAttribute("hidden", "");
  dossierPark = null;
}

function cardEl(p, mode) {
  const wrap = document.createElement("article");
  wrap.className = "card";
  if (visited.has(slug(p))) wrap.classList.add("visited");
  if (saved.has(slug(p))) wrap.classList.add("saved");
  const been = document.createElement("button");
  been.type = "button";
  been.className = "been";
  been.title = "Been here";
  been.setAttribute("aria-pressed", visited.has(slug(p)) ? "true" : "false");
  const mark = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  mark.setAttribute("viewBox", "0 0 24 24");
  const mp = document.createElementNS("http://www.w3.org/2000/svg", "path");
  mp.setAttribute("fill", "none");
  mp.setAttribute("stroke", "currentColor");
  mp.setAttribute("stroke-width", "2.2");
  mp.setAttribute("d", "M5 12l5 5 9-10");
  mark.append(mp);
  been.append(mark);
  been.onclick = (e) => {
    e.stopPropagation();
    const id = slug(p);
    if (visited.has(id)) visited.delete(id);
    else visited.add(id);
    storeSet(VISIT_KEY, visited);
    renderAtlas();
    updateProgress();
    if (mapMode) draw();
    if (dossierPark && dossierPark.slug === p.slug) openDossier(p);
  };
  const pic = document.createElement("span");
  pic.className = "photo";
  setPhoto(pic, p);
  const body = document.createElement("button");
  body.type = "button";
  body.className = "body";
  const tag = document.createElement("small");
  tag.className = "kind-tag";
  tag.textContent = kindLabel(kindOf(p));
  const b = document.createElement("b");
  b.textContent = p.name;
  const small = document.createElement("small");
  small.textContent = `${fmt(p.acres)} acres · ${(p.states || []).join("/")}`;
  body.append(tag, b, small);
  body.onclick = () => {
    if (mode === "choose") choose(p);
    else openDossier(p);
  };
  wrap.append(been, pic, body);
  return wrap;
}

function matchesQuery(p, q) {
  if (!q) return true;
  const blob = `${p.name} ${(p.states || []).join(" ")} ${kindLabel(kindOf(p))}`.toLowerCase();
  return blob.includes(q);
}

function renderChooser(q = "") {
  const root = $("#chooserCards");
  root.textContent = "";
  const query = q.toLowerCase().trim();
  let hits = parks.filter((p) => {
    if (chooserKind !== "all" && kindOf(p) !== chooserKind) return false;
    return matchesQuery(p, query);
  });
  hits.sort((a, b) => b.acres - a.acres);
  const needQuery = hits.length > CARD_CAP && query.length < 2;
  if (needQuery) hits = hits.slice(0, CARD_CAP);
  if (!hits.length) {
    const empty = document.createElement("p");
    empty.textContent = "Nothing by that name. Try Tongass, Anza-Borrego, or Zion.";
    root.append(empty);
    return;
  }
  hits.forEach((p) => root.append(cardEl(p, "choose")));
}

function atlasList() {
  const q = ($("#atlasSearch").value || "").toLowerCase().trim();
  return parks.filter((p) => {
    if (kindFilter !== "all" && kindOf(p) !== kindFilter) return false;
    if (stateFilter && !(p.states || []).includes(stateFilter)) return false;
    if (q && !matchesQuery(p, q)) return false;
    const id = slug(p);
    if (listFilter === "been") return visited.has(id);
    if (listFilter === "saved") return saved.has(id);
    if (listFilter === "left") return !visited.has(id);
    return true;
  }).sort((a, b) => b.acres - a.acres);
}

function renderAtlas() {
  const q = ($("#atlasSearch").value || "").toLowerCase().trim();
  const root = $("#allCards");
  root.textContent = "";
  let list = atlasList();
  const total = list.length;
  const capped = list.length > CARD_CAP && q.length < 2 && listFilter === "all";
  if (capped) list = list.slice(0, CARD_CAP);
  $("#atlasNote").textContent = capped
    ? `Showing the ${CARD_CAP} largest of ${fmt(total)}. Search or pick a state to see the rest.`
    : `${fmt(total)} in this list.`;
  if (!list.length) {
    const empty = document.createElement("p");
    empty.textContent = "Nothing in this list yet.";
    root.append(empty);
    return;
  }
  list.forEach((p) => root.append(cardEl(p, "dossier")));
}

function fillStatePick() {
  const sel = $("#statePick");
  const prev = sel.value;
  const states = [...new Set(parks.filter((p) => kindFilter === "all" || kindOf(p) === kindFilter).flatMap((p) => p.states || []))].sort();
  sel.textContent = "";
  const all = document.createElement("option");
  all.value = "";
  all.textContent = "All states";
  sel.append(all);
  states.forEach((st) => {
    const opt = document.createElement("option");
    opt.value = st;
    opt.textContent = st;
    sel.append(opt);
  });
  sel.value = states.includes(prev) ? prev : "";
  stateFilter = sel.value;
}

function renderFilters() {
  const root = $("#filters");
  root.textContent = "";

  const addChip = (id, label, active, onClick) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "chip kind";
    btn.classList.toggle("on", active);
    btn.textContent = label;
    btn.onclick = onClick;
    root.append(btn);
  };

  addChip("all", `All places (${fmt(parks.length)})`, listFilter === "all" && kindFilter === "all", () => {
    kindFilter = "all";
    listFilter = "all";
    fillStatePick();
    renderFilters();
    renderAtlas();
    if (mapMode) draw();
  });

  addChip("been", "Been there", listFilter === "been", () => {
    listFilter = "been";
    kindFilter = "all";
    fillStatePick();
    renderFilters();
    renderAtlas();
    if (mapMode) draw();
  });

  addChip("saved", "Saved", listFilter === "saved", () => {
    listFilter = "saved";
    kindFilter = "all";
    fillStatePick();
    renderFilters();
    renderAtlas();
    if (mapMode) draw();
  });

  KINDS.forEach((k) => {
    addChip(k.id, `${k.label} (${fmt(kindCount(k.id))})`, listFilter === "all" && kindFilter === k.id, () => {
      kindFilter = k.id;
      listFilter = "all";
      fillStatePick();
      renderFilters();
      renderAtlas();
      if (mapMode) draw();
    });
  });
}

function renderChooserKinds() {
  const root = $("#chooserKinds");
  root.textContent = "";
  [{ id: "all", label: "All" }, ...KINDS].forEach((k) => {
    const btn = document.createElement("button");
    btn.type = "button";
    btn.className = "chip kind";
    btn.classList.toggle("on", chooserKind === k.id);
    btn.textContent = k.label;
    btn.onclick = () => {
      chooserKind = k.id;
      renderChooserKinds();
      renderChooser($("#search").value);
    };
    root.append(btn);
  });
}

function openChooser(role) {
  picking = role;
  $("#chooser").hidden = false;
  $("#chooserTitle").textContent = role === "big" ? "Pick the larger place" : "Pick the smaller place";
  $("#search").value = "";
  chooserKind = "all";
  renderChooserKinds();
  renderChooser();
  $("#search").focus();
}
function closeChooser() {
  picking = null;
  $("#chooser").hidden = true;
}
function choose(p) {
  if (picking === "big") bigName = p.slug;
  else smallName = p.slug;
  focus = p.slug;
  closeChooser();
  draw();
  window.scrollTo({ top: 0, behavior: "smooth" });
}
function randomPair() {
  const pool = parks.filter((p) => kindOf(p) === kindFilter || kindFilter === "all");
  const src = pool.length > 1 ? pool : parks;
  const a = src[Math.floor(Math.random() * src.length)];
  let b = src[Math.floor(Math.random() * src.length)];
  if (b.slug === a.slug) b = src[(src.indexOf(a) + 7) % src.length];
  bigName = a.slug;
  smallName = b.slug;
  focus = a.slug;
  draw();
}
function hideOnboard() {
  const el = $("#onboard");
  el.hidden = true;
  el.setAttribute("hidden", "");
  try {
    localStorage.setItem(KEY, "1");
  } catch (e) {}
}
function showOnboard(i = 0) {
  obStep = i;
  const el = $("#onboard");
  el.hidden = false;
  el.removeAttribute("hidden");
  $("#obTitle").textContent = STEPS[i].title;
  $("#obCopy").textContent = STEPS[i].copy;
  $("#obDots").textContent = `${i + 1} / ${STEPS.length}`;
  $("#obNext").textContent = i === STEPS.length - 1 ? "See the parks" : "Next";
  $("#obSkip").hidden = i === STEPS.length - 1;
  $("#obNext").focus();
}

function boot() {
  visited = loadSet(VISIT_KEY);
  saved = loadSet(SAVE_KEY);
  const hash = decodeURIComponent((location.hash || "").replace(/^#/, ""));
  if (hash.includes("/")) {
    const [a, b] = hash.split("/");
    if (byId(a) && byId(b)) {
      bigName = byId(a).slug;
      smallName = byId(b).slug;
    }
  }
  $("#pickBig").onclick = () => openChooser("big");
  $("#pickSmall").onclick = () => openChooser("small");
  $("#closeChooser").onclick = closeChooser;
  $("#btnSwap").onclick = () => {
    const t = bigName;
    bigName = smallName;
    smallName = t;
    draw();
  };
  $("#btnShuffle").onclick = randomPair;
  $("#btnHelp").onclick = () => showOnboard(0);
  $("#btnMap").onclick = () => setMapMode(!mapMode);
  $("#focusState").onchange = (e) => {
    focusStateOnly = e.target.checked;
    if (mapMode) {
      fitMapToMarkers();
      draw();
    }
  };
  $("#connectVisited").onchange = (e) => {
    connectVisited = e.target.checked;
    if (mapMode) draw();
  };
  $("#btnFit").onclick = () => {
    fitMapToMarkers();
    draw();
  };
  $("#btnArt").onclick = openArt;
  $("#closeArt").onclick = closeArt;
  $("#artUsa").onclick = () => {
    artKind = "usa";
    paintArt();
  };
  $("#artPark").onclick = () => {
    artKind = "park";
    paintArt();
  };
  $("#artConnect").onchange = paintArt;
  $("#artDownload").onclick = downloadArt;
  $("#artPrint").onclick = printArt;
  $("#obSkip").onclick = (e) => {
    e.preventDefault();
    e.stopPropagation();
    hideOnboard();
  };
  $("#obNext").onclick = (e) => {
    e.preventDefault();
    e.stopPropagation();
    if (obStep >= STEPS.length - 1) hideOnboard();
    else showOnboard(obStep + 1);
  };
  $("#onboard").addEventListener("click", (e) => {
    if (e.target.id === "onboard") hideOnboard();
  });
  $("#openDossier").onclick = () => {
    const p = byId(focus);
    if (p) openDossier(p);
  };
  $("#closeDossier").onclick = closeDossier;
  $("#beenHere").onclick = () => {
    if (!dossierPark) return;
    const id = slug(dossierPark);
    if (visited.has(id)) visited.delete(id);
    else visited.add(id);
    storeSet(VISIT_KEY, visited);
    openDossier(dossierPark);
    renderAtlas();
    updateProgress();
    if (mapMode) draw();
  };
  $("#savePark").onclick = () => {
    if (!dossierPark) return;
    const id = slug(dossierPark);
    if (saved.has(id)) saved.delete(id);
    else saved.add(id);
    storeSet(SAVE_KEY, saved);
    openDossier(dossierPark);
    renderAtlas();
    updateProgress();
    if (mapMode) draw();
  };
  $("#comparePark").onclick = () => {
    if (!dossierPark) return;
    smallName = dossierPark.slug;
    focus = dossierPark.slug;
    closeDossier();
    draw();
    window.scrollTo({ top: 0, behavior: "smooth" });
  };
  $("#statePick").onchange = (e) => {
    stateFilter = e.target.value;
    renderAtlas();
    if (mapMode) draw();
  };
  $("#atlasSearch").oninput = (e) => {
    renderAtlas();
    if (mapMode) draw();
  };
  document.addEventListener("keydown", (e) => {
    if (e.key !== "Escape") return;
    if (!$("#onboard").hidden) hideOnboard();
    if (!$("#chooser").hidden) closeChooser();
    if (!$("#dossier").hidden) closeDossier();
    if ($("#artModal") && !$("#artModal").hidden) closeArt();
  });
  $("#search").oninput = (e) => renderChooser(e.target.value);
  const map = $("#map");
  map.addEventListener(
    "wheel",
    (e) => {
      if (!mapMode) return;
      e.preventDefault();
      const scaleBy = e.deltaY < 0 ? 1.12 : 0.9;
      mapScale = Math.min(10, Math.max(0.4, mapScale * scaleBy));
      syncMapTransform();
    },
    { passive: false }
  );
  map.addEventListener("pointerdown", (e) => {
    if (!mapMode) return;
    map.setPointerCapture(e.pointerId);
    mapDrag = { x: e.clientX, y: e.clientY, tx: mapTx, ty: mapTy };
  });
  map.addEventListener("pointermove", (e) => {
    if (!mapMode || !mapDrag) return;
    mapTx = mapDrag.tx + (e.clientX - mapDrag.x) / 180;
    mapTy = mapDrag.ty + (e.clientY - mapDrag.y) / 180;
    syncMapTransform();
  });
  map.addEventListener("pointerup", (e) => {
    if (mapDrag) {
      mapDrag = null;
      map.releasePointerCapture(e.pointerId);
    }
  });
  map.addEventListener("pointerleave", () => {
    mapDrag = null;
  });
  fillStatePick();
  renderFilters();
  draw();
  renderAtlas();
  try {
    if (!localStorage.getItem(KEY)) showOnboard(0);
  } catch (e) {}
}

Promise.all([
  fetch("parks.json").then((r) => r.json()),
  fetch("shapes.json").then((r) => r.json()),
  fetch("lands.json").then((r) => r.json()),
  fetch("land-shapes.json").then((r) => r.json()),
])
  .then(([meta, geo, lands, landGeo]) => {
    const npShapes = Object.fromEntries(geo.parks.map((s) => [s.name, s]));
    const np = meta.filter((p) => npShapes[p.name]).map((p) => ({
      ...p,
      kind: "national_park",
      shape: npShapes[p.name],
    }));
    if (np.length < 63) throw new Error("missing parks");
    const extras = lands.map((p, i) => ({ ...p, shape: landGeo.lands[i] })).filter((p) => p.shape && p.shape.d);
    parks = np.concat(extras);
    boot();
  })
  .catch(() => {
    document.body.insertAdjacentText("afterbegin", "Could not load park data. Refresh and try again.");
  });
